// Devuelve UN solo item: el nodo HTTP que va despues hace una sola peticion.
// Se guarda el rango (hoy y los ultimos 30 dias) y se conserva lo que traia el webhook
// (la query, para poder pedir el panel en JSON).
const entrada = $input.first().json ?? {};

const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());
const desde = new Date(hoy + 'T00:00:00Z');
desde.setUTCDate(desde.getUTCDate() - 30);

return [{ json: { ...entrada, ok: true, hoy, desde: desde.toISOString().slice(0, 10) } }];

// La fecha de hoy se calcula primero: se usa en el resto del panel.
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Europe/Madrid', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());
const mes = hoy.slice(0, 7);

// Monta el panel de Marisa con los datos de la tienda.
//
// Las cifras salen de la API (la app es la que las calcula); aqui solo se suman
// y se pinta. Si el panel se pide en JSON, se devuelve el mismo dato en JSON.
const entrada = $input.first().json ?? {};

const ventas = $('Ventas del periodo').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((x) => x && x.id !== undefined);
const abonos = $('Abonos del periodo').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((x) => x && x.id !== undefined);
const apartados = $('Apartados').all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((x) => x && x.id !== undefined);
const resumen = $('Resumen de la tienda').first().json ?? {};

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const redondear = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;

const ventasHoy = ventas.filter((v) => String(v.fecha ?? '') === hoy);
const abonosHoy = abonos.filter((a) => String(a.fecha ?? '') === hoy);

const totalVentas = redondear(ventasHoy.reduce((s, v) => s + Number(v.importe ?? 0), 0));
const totalAbonos = redondear(abonosHoy.reduce((s, a) => s + Number(a.importe ?? 0), 0));
const totalDia = redondear(totalVentas + totalAbonos);

const activos = apartados.filter((a) => String(a.estado) === 'activo');
const pendiente = redondear(activos.reduce((s, a) => s + Number(a.pendiente ?? 0), 0));


// Apartados que vencen en los proximos 30 dias.
const enDias = (limite) => Math.round(
  (new Date(String(limite) + 'T00:00:00Z').getTime() - new Date(hoy + 'T00:00:00Z').getTime()) / 86400000,
);
const proximos = activos
  .map((a) => ({ apartado: a, dias: enDias(a.fecha_limite) }))
  .filter((x) => x.dias >= 0 && x.dias <= 30)
  .sort((a, b) => a.dias - b.dias);

const recaudacionMes = redondear(
  ventas.filter((v) => String(v.fecha ?? '').slice(0, 7) === mes).reduce((s, v) => s + Number(v.importe ?? 0), 0)
  + abonos.filter((a) => String(a.fecha ?? '').slice(0, 7) === mes).reduce((s, a) => s + Number(a.importe ?? 0), 0),
);
const ventasMes = ventas.filter((v) => String(v.fecha ?? '').slice(0, 7) === mes).length;
const abonosMes = abonos.filter((a) => String(a.fecha ?? '').slice(0, 7) === mes).length;

const datos = {
  fecha: hoy,
  hoy: { ventas: totalVentas, abonos: totalAbonos, total: totalDia, num_ventas: ventasHoy.length, num_abonos: abonosHoy.length },
  mes: { recaudacion: recaudacionMes, num_ventas: ventasMes, num_abonos: abonosMes },
  pendiente_cobro: pendiente,
  apartados: {
    activos: activos.length,
    liquidados: resumen.liquidado ?? 0,
    vencidos: resumen.vencido ?? 0,
    total: resumen.total ?? apartados.length,
  },
  por_vencer: proximos.map((x) => ({
    id: x.apartado.id,
    cliente: x.apartado.cliente,
    producto: x.apartado.producto,
    talla: x.apartado.talla,
    pendiente: x.apartado.pendiente,
    fecha_limite: x.apartado.fecha_limite,
    dias: x.dias,
  })),
};

// Si se pide en JSON, se devuelve el dato y ya esta.
// La query se pierde en los nodos HTTP (sustituyen el item), asi que se lee
// del nodo que la guardo: ?formato=json devuelve los datos en JSON.
const query = $('Preparar').first().json?.query ?? {};
const formato = String(query.formato ?? entrada.query?.formato ?? 'html').toLowerCase();
if (formato === 'json') {
  return [{ json: { panel: datos, respuesta: JSON.stringify(datos, null, 2), formato: 'json' } }];
}

const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const filasProximos = proximos.length
  ? proximos.map((x) => `
        <tr>
          <td>${escapar(x.apartado.cliente)}</td>
          <td>${escapar([x.apartado.producto, x.apartado.talla].filter(Boolean).join(' · '))}</td>
          <td class="num">${euros(x.apartado.pendiente)}</td>
          <td>${escapar(x.apartado.fecha_limite ?? '')}</td>
          <td><span class="chip ${x.dias <= 7 ? 'chip-urgent' : ''}">${x.dias === 0 ? 'hoy' : x.dias + ' días'}</span></td>
        </tr>`).join('')
  : '<tr><td colspan="5" class="vacio">No hay apartados que vencen en los próximos 30 días</td></tr>';

const html = `<!doctype html>
<html lang="es" data-tema="claro">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="60">
<title>Panel de la tienda · Paso Firme</title>
<script>
// El tema se aplica antes de pintar la pagina: si no, se ve un destello del otro tema.
// Prioridad: lo que eligio el usuario, si no, el del sistema.
(function () {
  try {
    const guardado = localStorage.getItem('tema-paso-firme');
    const oscuroDelSistema = window.matchMedia('(prefers-color-scheme: dark)').matches;
    document.documentElement.setAttribute('data-tema', guardado || (oscuroDelSistema ? 'oscuro' : 'claro'));
  } catch (e) {
    document.documentElement.setAttribute('data-tema', 'claro');
  }
})();
</script>
<style>
  :root, :root[data-tema="claro"] {
    --fondo: #f5f3ef; --tarjeta: #ffffff; --texto: #241f1b; --suave: #6f675f;
    --borde: #e4ded5; --acento: #2f6f4f; --ambar: #b26a00; --rojo: #a3341f;
    --chip-fondo: #eef1ee; --chip-texto: #2f6f4f;
    --chip-rojo-fondo: #fdeee9; --chip-rojo-texto: #a3341f;
    --sombra: 0 6px 24px rgba(0, 0, 0, .08);
    --boton: #ffffff; --boton-texto: #241f1b;
  }
  :root[data-tema="oscuro"] {
    --fondo: #141210; --tarjeta: #1e1b18; --texto: #ece7e0; --suave: #a49a90;
    --borde: #322d28; --acento: #63c795; --ambar: #e0a33c; --rojo: #e8775f;
    --chip-fondo: #2a2622; --chip-texto: #63c795;
    --chip-rojo-fondo: #3a2320; --chip-rojo-texto: #e8775f;
    --sombra: 0 6px 24px rgba(0, 0, 0, .45);
    --boton: #262320; --boton-texto: #ece7e0;
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--fondo); color: var(--texto);
         font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
         -webkit-font-smoothing: antialiased; }
  main { max-width: 900px; margin: 0 auto; padding: 1.25rem 1rem 3rem; }
  header { display: flex; flex-wrap: wrap; align-items: center; gap: .5rem 1rem; margin-bottom: 1.25rem; }
  h1 { font-size: 1.35rem; margin: 0; flex: 1 1 auto; }
  .fecha { color: var(--suave); font-size: .9rem; }
  .boton { background: var(--boton); color: var(--boton-texto); border: 1px solid var(--borde);
           border-radius: 999px; width: 2.4rem; height: 2.4rem; font-size: 1rem; cursor: pointer;
           line-height: 1; }
  .boton:hover { border-color: var(--acento); }
  .cifras { display: grid; gap: .75rem; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); margin-bottom: 1.25rem; }
  .cifra { background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 14px; padding: 1rem 1.1rem; }
  .cifra .etiqueta { color: var(--suave); font-size: .8rem; text-transform: uppercase; letter-spacing: .04em; }
  .cifra .valor { font-size: 1.5rem; font-weight: 700; margin-top: .25rem; }
  .cifra .nota { color: var(--suave); font-size: .8rem; margin-top: .2rem; }
  .destacada { border-color: var(--acento); }
  .panel { background: var(--tarjeta); border: 1px solid var(--borde); border-radius: 14px; padding: 1rem 1.1rem 1.2rem; }
  .panel h2 { font-size: 1rem; margin: 0 0 .75rem; }
  table { width: 100%; border-collapse: collapse; font-size: .92rem; }
  th, td { text-align: left; padding: .55rem .4rem; border-bottom: 1px solid var(--borde); }
  th { color: var(--suave); font-weight: 600; font-size: .78rem; text-transform: uppercase; letter-spacing: .04em; }
  td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
  .chip { display: inline-block; padding: .1rem .5rem; border-radius: 999px; background: var(--chip-fondo);
          color: var(--chip-texto); font-size: .78rem; font-weight: 600; }
  .chip-urgent { background: var(--chip-rojo-fondo); color: var(--chip-rojo-texto); }
  .vacio { color: var(--suave); text-align: center; padding: 1.2rem 0; }
  footer { margin-top: 1.5rem; color: var(--suave); font-size: .8rem; text-align: center; }
  a { color: var(--acento); }
  @media (max-width: 560px) {
    main { padding: 1rem .75rem 2.5rem; }
    .cifra .valor { font-size: 1.3rem; }
    th:nth-child(2), td:nth-child(2) { display: none; }
    .fecha { width: 100%; }
  }
  @media (prefers-reduced-motion: no-preference) {
    .boton, .cifra, .panel { transition: background-color .2s ease, border-color .2s ease, color .2s ease; }
  }
</style>
</head>
<body>
<main>
  <header>
    <h1>Zapatería Paso Firme</h1>
    <span class="fecha">${escapar(datos.fecha)} · se actualiza cada minuto</span>
    <button id="tema" class="boton" type="button" title="Cambiar entre tema claro y oscuro" aria-label="Cambiar el tema">☀</button>
  </header>

  <section class="cifras">
    <div class="cifra destacada">
      <div class="etiqueta">Cobrado hoy</div>
      <div class="valor">${euros(datos.hoy.total)}</div>
      <div class="nota">${datos.hoy.num_ventas} ventas · ${datos.hoy.num_abonos} abonos</div>
    </div>
    <div class="cifra">
      <div class="etiqueta">Recaudado este mes</div>
      <div class="valor">${euros(datos.mes.recaudacion)}</div>
      <div class="nota">${datos.mes.num_ventas} ventas · ${datos.mes.num_abonos} abonos del mes</div>
    </div>
    <div class="cifra">
      <div class="etiqueta">Pendiente de cobro</div>
      <div class="valor">${euros(datos.pendiente_cobro)}</div>
      <div class="nota">${datos.apartados.activos} apartados activos</div>
    </div>
    <div class="cifra">
      <div class="etiqueta">Apartados</div>
      <div class="valor">${datos.apartados.activos} / ${datos.apartados.total}</div>
      <div class="nota">${datos.apartados.liquidados} liquidados · ${datos.apartados.vencidos} vencidos</div>
    </div>
  </section>

  <section class="panel">
    <h2>Se vencen en los próximos 30 días</h2>
    <table>
      <thead>
        <tr><th>Cliente</th><th>Producto</th><th class="num">Pendiente</th><th>Fecha límite</th><th>Quedan</th></tr>
      </thead>
      <tbody>${filasProximos}
      </tbody>
    </table>
  </section>

  <footer>
    Zapatería Paso Firme · datos de la app de la tienda ·
    <a href="/webhook/panel?formato=json">ver los datos en JSON</a>
  </footer>
</main>
<script>
// Interruptor de tema: guarda la eleccion en el navegador.
(function () {
  const boton = document.getElementById('tema');
  if (!boton) return;
  const pintar = () => {
    const oscuro = document.documentElement.getAttribute('data-tema') === 'oscuro';
    boton.textContent = oscuro ? '☀' : '☾';
    boton.setAttribute('aria-label', oscuro ? 'Cambiar al tema claro' : 'Cambiar al tema oscuro');
  };
  boton.addEventListener('click', () => {
    const oscuro = document.documentElement.getAttribute('data-tema') === 'oscuro';
    const nuevo = oscuro ? 'claro' : 'oscuro';
    document.documentElement.setAttribute('data-tema', nuevo);
    try { localStorage.setItem('tema-paso-firme', nuevo); } catch (e) { /* sin almacenamiento */ }
    pintar();
  });
  pintar();
})();
</script>
</body>
</html>`;

return [{ json: { panel: datos, html, respuesta: html, formato: 'html' } }];
